package upload

class ImageUploadCache(private val maxEntries: Int) {
    private val entries = LinkedHashMap<String, ByteArray>()

    fun put(key: String, chunk: ByteArray) {
        if (entries.size >= maxEntries) {
            entries.remove(entries.keys.first())
        }
        entries[key] = chunk
    }
}

